    async def selectItem(self, caseNumber):
        db = Prisma()
        await db.connect()

        items = await db.item.find_many(
            where={
                'caseNumber': caseNumber,
            }
        )
        await db.disconnect()

        return len(items)

    async def selectItemByCaseIndex(self, caseIndex, itemNumber):
        db = Prisma()
        await db.connect()
        items = await db.item.count(
            where={
                'caseIndex': caseIndex,
                'itemNumber': itemNumber
            }
        )
        await db.disconnect()

        if items == 0:
            return True
        else:
            return False

